package com.pis.scan;
import java.util.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class ScanFormatTest {
 @Test void exactSyntheticHeaderRetainsAllIdentityAndNeverClaimsImageDecode(){var p=UUID.randomUUID();var c=UUID.randomUUID();var s=UUID.randomUUID();String barcode=com.pis.label.LabelBarcode.create(s);var data=ScanFormat.fixture(p,c,s,barcode,32,64);var r=ScanFormat.inspect(data);assertThat(r.code()).isEqualTo("SYNTHETIC_HEADER_ONLY");assertThat(r.patientId()).isEqualTo(p);assertThat(r.caseId()).isEqualTo(c);assertThat(r.slideId()).isEqualTo(s);assertThat(r.barcode()).isEqualTo(barcode);assertThat(r.width()).isEqualTo(32);}
 @Test void tiffMagicIsNotVendorCompatibilityAndArchivesNeverExtract(){for(byte[] magic:List.of(new byte[]{'I','I',42,0},new byte[]{'M','M',0,42},new byte[]{'I','I',43,0},new byte[]{'M','M',0,43}))assertThat(ScanFormat.inspect(magic).code()).isEqualTo("FORMAT_NOT_CONFIGURED");assertThat(ScanFormat.inspect(new byte[]{'P','K',3,4}).code()).isEqualTo("UNSUPPORTED_ARCHIVE");assertThat(ScanFormat.inspect("../../etc/passwd".getBytes(java.nio.charset.StandardCharsets.US_ASCII)).code()).isEqualTo("UNSUPPORTED_FORMAT");}
 @Test void truncatedOversizedAndInvalidDimensionsFailClosed(){UUID id=UUID.randomUUID();var data=ScanFormat.fixture(id,id,id,com.pis.label.LabelBarcode.create(id),4097,1);assertThat(ScanFormat.inspect(data).code()).isEqualTo("CORRUPT_SYNTHETIC");assertThat(ScanFormat.inspect(Arrays.copyOf(data,ScanFormat.TRANSPORT.length+10)).code()).isEqualTo("CORRUPT_SYNTHETIC");assertThat(ScanFormat.inspect(new byte[513]).code()).isEqualTo("INPUT_LIMIT");data=ScanFormat.fixture(id,id,id,com.pis.label.LabelBarcode.create(id),1,1);data[ScanFormat.TRANSPORT.length+8+48+33]='?';assertThat(ScanFormat.inspect(data).code()).isEqualTo("CORRUPT_SYNTHETIC");}
 @Test void leaseBoundaryAndBackoffUseExplicitFrozenTime(){var start=java.time.Instant.parse("2026-01-01T00:00:00Z");var deadline=ScanLeasePolicy.deadline(start);assertThat(ScanLeasePolicy.expired(deadline,deadline.minusNanos(1))).isFalse();assertThat(ScanLeasePolicy.expired(deadline,deadline)).isTrue();assertThat(ScanLeasePolicy.retryAt(start,3)).isEqualTo(start.plusSeconds(15));assertThatThrownBy(()->ScanLeasePolicy.retryAt(start,4)).isInstanceOf(IllegalArgumentException.class);}
}
